    for (int j = 0; j < sorted.length - i - 1; ++j) {
      if (sorted[j] > sorted[j + 1]) {
        int temp = sorted[j];
        sorted[j] = sorted[j + 1];
        sorted[j + 1] = temp;
        swapped = true;
      }
    }

