int maxFill(List<List<int>> grid, int capacity) {
  int rows = grid.length;
  int cols = grid[0].length;

  // Initialize visited matrix to keep track of filled cells.
  List<List<bool>> visited = List.generate(rows, (_) => List.filled(cols, false));

  // Recursive function for DFS traversal and filling the connected component.
  void dfs(int row, int col) {
    if (row < 0 || row >= rows || col < 0 || col >= cols || 
        grid[row][col] != 1 || visited[row][col]) return;

    visited[row][col] = true;

    // Fill the current cell with water.
    grid[row][col] = 2;

    // Explore all four directions: up, down, left, right.
    dfs(row - 1, col); // Up
    dfs(row + 1, col); // Down
    dfs(row, col - 1); // Left
    dfs(row, col + 1); // Right
  }

  // Iterate through each cell in the grid.
  for (int i = 0; i < rows; i++) {
    for (int j = 0; j < cols; j++) {
      // If a land cell is found, perform DFS to fill it and its connected components.
      if (grid[i][j] == 1) {
        dfs(i, j);

        // Check how many cells were filled by this DFS call.
        int filledCells = 0;
        for (int k = 0; k < rows; k++) {
          for (int l = 0; l < cols; l++) {
            if (visited[k][l]) filledCells++;
          }
        }

        // Calculate the remaining capacity after filling.
        int remainingCapacity = capacity - filledCells;

        // Return early if there's no more capacity or if we've already exceeded capacity.
        if (remainingCapacity <= 0) {
          break;
        } else {
          capacity -= filledCells;
        }
      }
    }
  }

  // After completing DFS on all possible components, calculate the total number of filled cells.
  int totalFilledCells = 0;
