    while(opsStack.isNotEmpty){
      String topOp = opsStack.pop();
      int b = numsStack.pop();
      int a = numsStack.pop()!;

      switch(topOp) {
        case '+': result = a + b; break;
        case '-': result = a - b; break;
        case '*': result = a * b; break;
        case '/': result = ~/a~/b; break;
      }
    }
  }

